"""Shipment records."""


class Shipment:
    def __init__(self, route, weight):
        self.route = route
        self.weight = weight

    def __repr__(self):
        return "Shipment(%r, %r)" % (self.route, self.weight)


ROWS = [('r22', 29), ('r47', 20), ('r47', 16), ('r22', 10), ('r22', 7), ('r10', 6), ('r22', 34)]


def load_shipments():
    """Yield the stored shipments one at a time."""
    for route, weight in ROWS:
        yield Shipment(route, weight)


def feed_shipments():
    """Endless feed of shipments: repeats the stored rows for ever."""
    while True:
        for route, weight in ROWS:
            yield Shipment(route, weight)

