"""Windows over the shipments feed."""
import itertools


def summarize_window(feed, size):
    """Read the next `size` shipments from the feed and return (peak weight, list of weight).

    The feed may be endless. Exactly `size` items are read from it.
    """
    window = itertools.islice(feed, size)
    peak = max(x.weight for x in window)
    values = [x.weight for x in window]
    return peak, values


def group_by_route(shipments):
    """Return a dict from route to the list of shipments with that route."""
    groups = {}
    for x in shipments:
        groups.setdefault(x.route, []).append(x)
    return groups


def describe_shipment(shipment):
    """Return a one-line description of a shipment."""
    return "%s: %s" % (shipment.route, shipment.weight)
